//! Auto-update prompting and execution.

use crate::error::{BivvyError, Result};
use std::process::Command;

use super::{check_for_updates, detect_install_method, InstallMethod, UpdateInfo};
use crate::ui::{OutputWriter, Prompt, PromptResult, PromptType, UserInterface};

/// Check for updates and prompt user if update available.
///
/// Returns true if an update was executed.
///
/// Requires full `UserInterface` — uses `OutputWriter` (messages),
/// `Prompter` (confirm prompt), and `UiState` (interactivity check).
pub fn check_and_prompt_update(ui: &mut dyn UserInterface) -> Result<bool> {
    // Only check in interactive mode
    if !ui.is_interactive() {
        return Ok(false);
    }

    // Check for updates
    let info = match check_for_updates() {
        Some(info) => info,
        None => return Ok(false),
    };

    // No update available
    if !info.update_available {
        return Ok(false);
    }

    // Detect install method
    let method = detect_install_method();

    // Prompt for update
    if prompt_for_update(ui, &info, &method)? {
        execute_update(&method)?;
        return Ok(true);
    }

    Ok(false)
}

/// Prompt the user to update.
fn prompt_for_update(
    ui: &mut dyn UserInterface,
    info: &UpdateInfo,
    method: &InstallMethod,
) -> Result<bool> {
    ui.message(&format!(
        "A new version of bivvy is available: {} -> {}",
        info.current, info.latest
    ));

    if !method.supports_auto_update() {
        if let Some(url) = &info.release_url {
            ui.message(&format!("Download from: {}", url));
        }
        return Ok(false);
    }

    let prompt = Prompt {
        key: "update_bivvy".to_string(),
        question: "Would you like to update now?".to_string(),
        prompt_type: PromptType::Confirm,
        default: Some("true".to_string()),
    };

    match ui.prompt(&prompt)? {
        PromptResult::Bool(confirmed) => Ok(confirmed),
        _ => Ok(false),
    }
}

/// Execute the update using the appropriate method.
fn execute_update(method: &InstallMethod) -> Result<()> {
    let command = method
        .update_command()
        .ok_or_else(|| BivvyError::UpdateError {
            message: "No update command for install method".to_string(),
        })?;

    let parts: Vec<&str> = command.split_whitespace().collect();
    if parts.is_empty() {
        return Err(BivvyError::UpdateError {
            message: "Empty update command".to_string(),
        });
    }

    let status = Command::new(parts[0]).args(&parts[1..]).status()?;

    if !status.success() {
        return Err(BivvyError::UpdateError {
            message: format!(
                "Update command failed with exit code: {:?}",
                status.code()
            ),
        });
    }

    Ok(())
}

/// Show update notification without prompting.
///
/// Only requires `OutputWriter` — displays a message but does not prompt.
pub fn show_update_notification(ui: &mut dyn OutputWriter) {
    if let Some(info) = check_for_updates() {
        if info.update_available {
            ui.message(&format!(
                "Update available: {} -> {} (run `bivvy update` to upgrade)",
                info.current, info.latest
            ));
        }
    }
}

/// Thread-safe flag for suppressing update notifications within the current process.
static SUPPRESS_UPDATE: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

/// Suppress update notification for the current session.
///
/// Uses a process-local atomic flag instead of mutating the environment.
pub fn suppress_notification() {
    SUPPRESS_UPDATE.store(true, std::sync::atomic::Ordering::Relaxed);
}

/// Check if update notification is suppressed.
pub fn is_notification_suppressed() -> bool {
    SUPPRESS_UPDATE.load(std::sync::atomic::Ordering::Relaxed)
}

